def full_DATA_decode(raw,parse=None):
    return sol143_native_check(_sol143_prior_full_DATA_decode(raw,parse))

def inert(raw):
    return sol143_native_check(_sol143_prior_inert(raw))

def _sol143_prior_full_DATA_decode(raw,parse=None):
    if raw[:4]==b'DS69' or raw[:8]==A201_REF_MAGIC:return sol069_decode(raw,PIPE_CAP,need,inert if parse is None else parse)

def a064_restore_metadata(producer,item,blob,need):
    path=tuple(item["path"])
    need(path in A064_META_PATHS and len(blob)==item["bytes"] and
        hashlib.sha256(blob).hexdigest()==item["sha256"],"A064_EXACT_METADATA_PATH_RAW_SHA")
    container=producer
    for key in path[:-1]:container=container[key]
    need(container[path[-1]] is None,"A064_METADATA_NOT_ALREADY_RESTORED")
    need(item["codec"] in ("fd64.v1","fd64.dict.v2","json.DATA.v1","string.DATA.sol067.v1","bounded.DATA.sol069.v1"),"A064_METADATA_CODEC")
    if item['codec'].startswith('fd64'):
        need(blob[:4]==(b'FD65' if item['codec']=='fd64.dict.v2' else b'FD64'),'A066_DECLARED_FULL_HISTORY_CODEC')
        container[path[-1]]=a064_fd_decode(blob,need)
    elif item['codec'] in ('string.DATA.sol067.v1','bounded.DATA.sol069.v1'):container[path[-1]]=a067_full_DATA_decode(blob)
    else:container[path[-1]]=json_DATA(blob)

def run_positive_first(positive,negative,case,*,positive_body_plane_fds=None,negative_body_plane_fds=None):
    need(case in CASES[1:] and positive[1]!=negative[1],"A079_FRESH_INDEPENDENT_PAIR")
    a,b=(os.fstat(bundle[0][122]) for bundle in (positive,negative))
    need((a.st_dev,a.st_ino)!=(b.st_dev,b.st_ino),"A079_FRESH_PROTECTED_VIEWS")
    need(all(positive[2][role]==negative[2][role] for role in SOURCES if role!=119),"A079_FULL_SOURCE_COMPLEMENT_BETWEEN_CASES")
    # A separate approved capsule binds each real view and single inert DATA
    # selector. No shared Root grant is invented from this pair or its result.
    pos=run_public(positive,"positive",body_plane_fds=positive_body_plane_fds)
    if not pos["accepted"]:
        return {"positive":pos,"negative":None,"negative_disposition":"NOT_RUN_POSITIVE_REFUSED",
            "body_credit":False,"whole_browser_credit":False,"SourceReady":False,"GO":False}
    neg=run_public(negative,case,body_plane_fds=negative_body_plane_fds)
    return {"positive":pos,"negative":neg,"source_ready":False,"current_GO":False,"full_registry_controls":"SOURCE_INCOMPLETE"}
